#!/usr/bin/env node
// STORE SHOTS, ONE COMMAND (T704; owner 2026-11-13: "store pictures should be an autogenerated thing"):
//   node app/tools/store-shots/run.mjs [--out DIR] [--at 2026-11-13T12:00:00-07:00] [--site https://staging.canifishthis.ca]
// Shoots the Play phone set (the 8 approved shots, store-shots.json) from the STAGING WEB SITE in headless Chrome (the same
// source as the approved set: it needs no emulator or APK, so it is the same on any machine and takes a few minutes), frames
// them at 1080x1920, and puts the 8 PNGs in DIR (default app/dist/store-shots/play-phone). No other argument is needed.
// PINNED: the page's clock (default: noon B.C. time today; B.C. is on permanent -07:00), light theme, phone 360x640 @3, the
// first-run/walkthrough/in-season notices seeded as seen, the saved-spot seed, the waters named by URL (Vedder, Chilliwack),
// the Conditions camera (10 km scale). NOT pinned: the live feeds (gauge readings, the forecast, DFO salmon notices) and the
// site's release; they are CHECKED instead (store-shots/checks.mjs asserts each shot's content on the page BEFORE the capture:
// salmon above the game-fish calendar, the forecast on the chart, more than one part on the river...). A failed check = no shot,
// no frames, exit 1, and `report.json` in DIR says which scene failed and why. Nothing is shot blank or stale.
import fs from 'node:fs'; import path from 'node:path';
import { spawnSync } from 'node:child_process';

const HERE = path.dirname(new URL(import.meta.url).pathname), APP = path.resolve(HERE, '../..');
const args = process.argv.slice(2), val = (k, d) => (args.includes(k) ? args[args.indexOf(k) + 1] : d);
for (const a of args) if (a.startsWith('--') && !['--out', '--at', '--site'].includes(a)) throw new Error(`store-shots/run: unknown flag ${a} (flags: --out, --at, --site)`);
const OUT = path.resolve(val('--out', path.join(APP, 'dist/store-shots/play-phone')));
const SITE = val('--site', 'https://staging.canifishthis.ca');
const bcToday = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Vancouver', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date());
const AT = val('--at', `${bcToday}T12:00:00-07:00`);
if (Number.isNaN(Date.parse(AT))) throw new Error(`store-shots/run: --at ${AT} is not a date`);

const { shots } = JSON.parse(fs.readFileSync(path.join(APP, 'tools/store-shots.json'), 'utf8'));
if (shots.length !== 8) throw new Error(`store-shots/run: the approved set is 8 shots, store-shots.json lists ${shots.length}`);

// the working folder is DIR/work (raw captures, framed output, the play-shots report); DIR itself ends holding only the 8 shots + report.json
const WORK = path.join(OUT, 'work');
fs.rmSync(OUT, { recursive: true, force: true }); fs.mkdirSync(WORK, { recursive: true });
console.log(`store-shots/run: site ${SITE}, clock pinned to ${AT}, light theme, phone 1080x1920 -> ${OUT}`);
const r = spawnSync(process.execPath, [path.join(APP, 'tools/store-shots.mjs'), '--only', 'play-phone', '--theme', 'light'],
  { stdio: 'inherit', cwd: APP, env: { ...process.env, STORE_SHOTS_DIR: WORK, STORE_SHOTS_SITE: SITE, PIN_AT: AT } });
const readReport = () => { try { return JSON.parse(fs.readFileSync(path.join(WORK, 'raw/play-shots-report.json'), 'utf8')); } catch { return null; } };
const rep = readReport();
const fail = (why) => { fs.writeFileSync(path.join(OUT, 'report.json'), JSON.stringify({ ok: false, site: SITE, pinAt: AT, why, scenes: rep?.scenes ?? null }, null, 2) + '\n');
  console.error(`store-shots/run: FAILED, nothing delivered: ${why}\n` + Object.entries(rep?.scenes ?? {}).filter(([, v]) => v !== 'ok').map(([k, v]) => `  ${k}: ${v}`).join('\n') + `\n  (details: ${path.join(OUT, 'report.json')}; the captures that passed are in ${path.join(WORK, 'raw')})`); process.exit(1); };
if (r.status !== 0) fail(`store-shots.mjs exited ${r.status}`);

// the 8 framed shots, exactly 1080x1920
const framed = path.join(WORK, 'store/light/play-phone');
const png = (f) => { const b = fs.readFileSync(f); return [b.readUInt32BE(16), b.readUInt32BE(20)]; };
const want = shots.map((s, i) => `${String(i + 1).padStart(2, '0')}-${s.scene}.png`);
for (const f of want) {
  const p = path.join(framed, f);
  if (!fs.existsSync(p)) fail(`${f} was not made`);
  const [w, h] = png(p); if (w !== 1080 || h !== 1920) fail(`${f} is ${w}x${h}, Play's phone size here is 1080x1920`);
  fs.copyFileSync(p, path.join(OUT, f));
}
fs.writeFileSync(path.join(OUT, 'report.json'), JSON.stringify({ ok: true, site: SITE, pinAt: AT, files: want, scenes: rep?.scenes ?? null }, null, 2) + '\n');
console.log(`store-shots/run: ${want.length} shots in ${OUT}`);
